import React from "react";

import {
  ResponsiveContainer,
  ComposedChart,
  Bar,
  Line,
  XAxis,
  YAxis,
  CartesianGrid,
  Tooltip,
  Legend,
} from "recharts";

import "./DashboardCharts.css";

// Temporary demo data.
// Replace with backend API data later.

const analyticsData = [
  { month: "May", revenue: 12000, paid: 30, pending: 15, overdue: 5 },
  { month: "Jun", revenue: 18000, paid: 40, pending: 12, overdue: 8 },
  { month: "Jul", revenue: 15000, paid: 35, pending: 18, overdue: 7 },
  { month: "Aug", revenue: 25000, paid: 50, pending: 15, overdue: 10 },
  { month: "Sep", revenue: 22000, paid: 45, pending: 20, overdue: 5 },
  { month: "Oct", revenue: 32000, paid: 60, pending: 12, overdue: 8 },
];

function DashboardCharts() {
  return (
    <div className="chart-card combined-chart">

      <div className="chart-heading">
        <div>
          <h3>Business Analytics</h3>
          <p>Revenue and invoice performance</p>
        </div>

        <span className="chart-period">Last 6 Months</span>
      </div>

      <ResponsiveContainer width="100%" height={350}>
        <ComposedChart
          data={analyticsData}
          margin={{ top: 10, right: 15, left: 10, bottom: 5 }}
        >
          <CartesianGrid
            strokeDasharray="3 3"
            vertical={false}
          />

          <XAxis
            dataKey="month"
            axisLine={false}
            tickLine={false}
          />

          <YAxis
            yAxisId="left"
            axisLine={false}
            tickLine={false}
          />

          <YAxis
            yAxisId="right"
            orientation="right"
            axisLine={false}
            tickLine={false}
            tickFormatter={(value) => `₹${value / 1000}k`}
          />

          <Tooltip
            formatter={(value, name) => {
              if (name === "Revenue") {
                return [`₹${value.toLocaleString("en-IN")}`, name];
              }

              return [value, name];
            }}
          />

          <Legend />

          <Bar
            yAxisId="left"
            dataKey="paid"
            name="Paid Invoices"
            fill="#16a34a"
            radius={[4, 4, 0, 0]}
          />

          <Bar
            yAxisId="left"
            dataKey="pending"
            name="Pending Invoices"
            fill="#f59e0b"
            radius={[4, 4, 0, 0]}
          />

          <Bar
            yAxisId="left"
            dataKey="overdue"
            name="Overdue Invoices"
            fill="#ef4444"
            radius={[4, 4, 0, 0]}
          />

          <Line
            yAxisId="right"
            type="monotone"
            dataKey="revenue"
            name="Revenue"
            stroke="#2563eb"
            strokeWidth={3}
            dot={{ r: 4 }}
          />

        </ComposedChart>
      </ResponsiveContainer>

    </div>
  );
}

export default DashboardCharts;
